import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"蒙","description":"焦氏易林注 - 蒙","frontmatter":{"title":"蒙","description":"焦氏易林注 - 蒙"},"headers":[],"relativePath":"zh/classics/jiaoyilin/004.md","filePath":"zh/classics/jiaoyilin/004.md"}'),l={name:"zh/classics/jiaoyilin/004.md"};function n(d,a,t,s,o,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="蒙" tabindex="-1">蒙 <a class="header-anchor" href="#蒙" aria-label="Permalink to “蒙”">​</a></h1><h3 id="蒙-1" tabindex="-1">蒙 <a class="header-anchor" href="#蒙-1" aria-label="Permalink to “蒙”">​</a></h3><h3 id="蒙之乾" tabindex="-1">蒙之乾 <a class="header-anchor" href="#蒙之乾" aria-label="Permalink to “蒙之乾”">​</a></h3><h3 id="林辞" tabindex="-1">林辞 <a class="header-anchor" href="#林辞" aria-label="Permalink to “林辞”">​</a></h3><p>海為水王，聽聖且明。百流歸德，無有畔逆，常饒優足。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>乾為海、為水、為王、為聰聖、為明、為百，《禹貢》：「匯漢朝宗於海，故百流歸德」，乾順行，故無有畔逆，乾富故常饒優足。</p><h3 id="蒙之坤" tabindex="-1">蒙之坤 <a class="header-anchor" href="#蒙之坤" aria-label="Permalink to “蒙之坤”">​</a></h3><h3 id="林辞-1" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-1" aria-label="Permalink to “林辞”">​</a></h3><p>左輔右弼，金玉滿堂。常盈不亡，富如敖倉。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>此全用《蒙》象。震為左，震反為右，震為輔弼，故曰左輔右弼。艮為金，震為玉，艮為堂、為厫倉，厫倉所以盛粟，震為粟，故尤切。○汲古本、宋元本首有「天之所有，禍不過家」二句，文義與下不屬，而元本家下一雲左輔右弼云云，是上二句確自為一林，非與下為一林，故刪上二句而附記於此。</p><h3 id="蒙之屯" tabindex="-1">蒙之屯 <a class="header-anchor" href="#蒙之屯" aria-label="Permalink to “蒙之屯”">​</a></h3><h3 id="林辞-2" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-2" aria-label="Permalink to “林辞”">​</a></h3><p>安息康居，異國穹廬。非吾習俗，使我心憂。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>坎位西。安息、康居，皆西方國。又中爻艮止，故曰安息康居。艮為國、為廬、為天，故曰穹廬。坤為我、為俗，坎為心、為憂。</p><h3 id="蒙之蒙" tabindex="-1">蒙之蒙 <a class="header-anchor" href="#蒙之蒙" aria-label="Permalink to “蒙之蒙”">​</a></h3><h3 id="林辞-3" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-3" aria-label="Permalink to “林辞”">​</a></h3><p>何草不黃，至未盡玄。室家分離，悲憂於心。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>震為草、為玄黃，坤貞。未，言草至未而將變色，《詩小雅》「何草不黃」「何草不玄」，箋：玄，赤黑色。艮為室家，二四艮覆，故曰分離。坎為心、為悲愁。○憂，依宋元本，汲古作愁。</p><h3 id="蒙之需" tabindex="-1">蒙之需 <a class="header-anchor" href="#蒙之需" aria-label="Permalink to “蒙之需”">​</a></h3><h3 id="林辞-4" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-4" aria-label="Permalink to “林辞”">​</a></h3><p>範公鴟夷，善賈飾資。東之營邱，易字子皮。把珠載金，多得利歸。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>坎為毒，故曰範公，范蠡也。《檀弓》：「範則冠而蟬有緌」是也。伏艮為鴟，鴟夷者，革囊，盛酒器。楊雄《酒箴》所謂「鴟夷滑稽，腹大如壺」是也。艮又為革，坎為酒，故曰鴟夷。《易林》用一字兼數象往往如是，範公鴟夷者，言范蠡適齊、號鴟夷子皮也。乾為資財。飾、飭，通治也。離為東，伏艮為營邱、為皮，伏坤為字，故曰易字子皮。艮為把、為金，反震為珠，坤為載、為利，兼用旁通。○鴟，依宋元本，汲古作陶，非。載金，依宋本，元本作戴，非。得利，汲古作福利，依宋元本。</p><h3 id="蒙之訟" tabindex="-1">蒙之訟 <a class="header-anchor" href="#蒙之訟" aria-label="Permalink to “蒙之訟”">​</a></h3><h3 id="林辞-5" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-5" aria-label="Permalink to “林辞”">​</a></h3><p>老楊日衰，條多枯枝。爵級不進，日下摧隤。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>巽木乾老，故曰老楊。離為日、為枯、為爵，巽為隕落，故摧隤。○下，依宋元本，汲古作乃。日下，依泰之咸校，宋元本作遂下，汲古作遂乃。</p><h3 id="蒙之師" tabindex="-1">蒙之師 <a class="header-anchor" href="#蒙之師" aria-label="Permalink to “蒙之師”">​</a></h3><h3 id="林辞-6" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-6" aria-label="Permalink to “林辞”">​</a></h3><p>小狐渡水，污濡其尾。利得無幾，與道合契。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>此用《蒙》象。上艮，故曰小狐、曰尾，坤坎皆為水，故污濡其尾。坤為財、為聚，坤虛，故得少。震為大塗，故曰道。坎為合、為信，故曰合契。○利，汲古作科，餘多作稍。無，汲古作其，契作符，皆非，依宋元本。</p><h3 id="蒙之比" tabindex="-1">蒙之比 <a class="header-anchor" href="#蒙之比" aria-label="Permalink to “蒙之比”">​</a></h3><h3 id="林辞-7" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-7" aria-label="Permalink to “林辞”">​</a></h3><p>豕生魚魴，鼠舞庭堂。姦侫施毒，上下昏荒，君失其邦。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>坎為豕，坤為魚、為育，故曰豕生魚魴。丁晏雲《開元占經》引京氏雲：「豕生魚魴，其邑犬水」是也。艮為鼠、為庭堂，艮手為舞，《漢書五行志》：「燕有黃鼠銜其尾舞王宮」，《京房易傳》曰：「誅不原情厥妖鼠舞門」是也。坎為毒、為姦，坎上下兌口相背，故曰姦侫。艮為上，坎為下、為昏荒、為邦，震為君，震覆，故失邦。○邦，元本作國，依汲古。</p><h3 id="蒙之小畜" tabindex="-1">蒙之小畜 <a class="header-anchor" href="#蒙之小畜" aria-label="Permalink to “蒙之小畜”">​</a></h3><h3 id="林辞-8" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-8" aria-label="Permalink to “林辞”">​</a></h3><p>天地配享，六位光明。陰陽順敘，以成厥功。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>乾天，伏坤為地，兌食故曰享。乾數六，離為光明，伏艮為位，故曰六位光明。乾陽巽順，乾為功。○厥功，從汲古，宋元本作和平。</p><h3 id="蒙之履" tabindex="-1">蒙之履 <a class="header-anchor" href="#蒙之履" aria-label="Permalink to “蒙之履”">​</a></h3><h3 id="林辞-9" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-9" aria-label="Permalink to “林辞”">​</a></h3><p>踝踵足傷，右指病癰。失旅後時，利走不歸。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>通《謙》。震為踝、為足，艮多節，故曰腫、曰傷、曰癰。《釋名》：踵，鍾也，聚也。義與腫同，與《易林》合。艮為指，兌為右，故曰右指。坎為孤、為失，故曰失旅。艮為時，震為後，故曰後時。震為走、為歸，坎陷，故不歸。○宋元本歸作來，從汲古。走不，汲古作不走，非，從宋元本。又右指病癰，元本作右足病擁，非。</p><h3 id="蒙之泰" tabindex="-1">蒙之泰 <a class="header-anchor" href="#蒙之泰" aria-label="Permalink to “蒙之泰”">​</a></h3><h3 id="林辞-10" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-10" aria-label="Permalink to “林辞”">​</a></h3><p>異體殊患，各有所屬。西鄰孤媼，欲寄我室。主母罵詈，求不可得。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>坤為體、為患害，乾陽坤陰，故曰異體殊患。六爻皆有應予，故曰各有所屬。兌為西、為孤媼，伏艮為室、為寄。震為主，坤為母，震言兌言，故曰主母罵詈。艮為求，艮伏，故求不可得。○異，汲古作思，殊患作同恩，求不可得作求子不得，皆非，今從宋元本。主母，依汲古，宋元本作王。</p><h3 id="蒙之否" tabindex="-1">蒙之否 <a class="header-anchor" href="#蒙之否" aria-label="Permalink to “蒙之否”">​</a></h3><h3 id="林辞-11" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-11" aria-label="Permalink to “林辞”">​</a></h3><p>操●鄉畝，祈貸稷黍。飲食充口，安和無咎。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>艮手為操，巽為●、為稷黍。坤為畝，乾為言，故曰祈貸，言以●為祭而祈田也。伏兌為口、為食，坤為安。○●即秬，黑黍也。宋元本作●，非。《書洛誥》以秬鬯二卣，秬鬯，皆祭品，言操秬至野祈田也。祈貸，宋元本作折貨，尤非。鄉，音向。安和，宋元本作安利，依汲古。</p><h3 id="蒙之同人" tabindex="-1">蒙之同人 <a class="header-anchor" href="#蒙之同人" aria-label="Permalink to “蒙之同人”">​</a></h3><h3 id="林辞-12" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-12" aria-label="Permalink to “林辞”">​</a></h3><p>新受大寵，福祿重來。樂且日富，蒙慶得財。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>離為新，乾為大、為寵、為福祿，重乾故曰重來。離日乾富，故曰日富。乾為慶、為財。○新受大寵，宋元本作所受大喜，依汲古。</p><h3 id="蒙之大有" tabindex="-1">蒙之大有 <a class="header-anchor" href="#蒙之大有" aria-label="Permalink to “蒙之大有”">​</a></h3><h3 id="林辞-13" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-13" aria-label="Permalink to “林辞”">​</a></h3><p>舉杯飲酒，無益溫寒。指直失取，亡利不歡。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>通《比》。坤為缶、為杯，艮為舉，坎為酒，兌為飲，離溫乾寒，時之自然，非酒所能改易也。艮為指、為取，乾為直，故指直失取，言指僵不能取物也。坤貧，故亡利。震覆，故不歡。○汲古三四句倒置，直作宜，均依宋元本。</p><h3 id="蒙之謙" tabindex="-1">蒙之謙 <a class="header-anchor" href="#蒙之謙" aria-label="Permalink to “蒙之謙”">​</a></h3><h3 id="林辞-14" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-14" aria-label="Permalink to “林辞”">​</a></h3><p>日月相望，光明盛昌。三聖茂承，功德大隆。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>坎月。伏離為日、為目，故曰日月相望。艮為光明，震為盛昌，坎為聖，艮納丙數三，故曰三聖。震為茂、為隆，伏乾為功德。</p><h3 id="蒙之豫" tabindex="-1">蒙之豫 <a class="header-anchor" href="#蒙之豫" aria-label="Permalink to “蒙之豫”">​</a></h3><h3 id="林辞-15" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-15" aria-label="Permalink to “林辞”">​</a></h3><p>猾夫爭強，民去其鄉。公孫叔子，戰於城南。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>坎為姦猾，震為夫、為強，坤為民、為鄉，震往，故民去其鄉。艮為叔、為孫，震為子，正反兩震相背，故曰戰。艮為城，震為南，故曰城南。下二句故實未詳。○城南，依汲古，宋元本作瀟湘，雖與上葉，似非。</p><h3 id="蒙之隨" tabindex="-1">蒙之隨 <a class="header-anchor" href="#蒙之隨" aria-label="Permalink to “蒙之隨”">​</a></h3><h3 id="林辞-16" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-16" aria-label="Permalink to “林辞”">​</a></h3><p>猿墮高木，不踒手足。保我金玉，還歸其室。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>巽為高，艮為猿，艮在震木上，故曰猿墮高木。艮手震足，兌折在外，故不踒。踒，折也。艮為金，震為玉、為歸，艮為室。○宋元本「保我金玉」在第四句，依汲古。金玉，汲古作全生，依宋元本。</p><h3 id="蒙之蠱" tabindex="-1">蒙之蠱 <a class="header-anchor" href="#蒙之蠱" aria-label="Permalink to “蒙之蠱”">​</a></h3><h3 id="林辞-17" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-17" aria-label="Permalink to “林辞”">​</a></h3><p>逐狐東山，水遏我前。深不可涉，失利後便。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>艮狐震逐，震東，艮山，故曰逐狐東山。互大坎，故曰水、曰深不可涉。巽為利，坎為失，故曰失利後便。○遏，汲古作過，依宋元本。</p><h3 id="蒙之臨" tabindex="-1">蒙之臨 <a class="header-anchor" href="#蒙之臨" aria-label="Permalink to “蒙之臨”">​</a></h3><h3 id="林辞-18" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-18" aria-label="Permalink to “林辞”">​</a></h3><p>鑿井求玉，非卞氏寶。名困身辱，勞無所得。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>震為玉，兌為井，伏艮為求。非卞氏寶，言求之非地也。艮為名，艮反故名困。坤為身、為下，故為辱。坤虛役萬物，故勞無所得。</p><h3 id="蒙之觀" tabindex="-1">蒙之觀 <a class="header-anchor" href="#蒙之觀" aria-label="Permalink to “蒙之觀”">​</a></h3><h3 id="林辞-19" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-19" aria-label="Permalink to “林辞”">​</a></h3><p>黃玉溫厚，君子所服。甘露溽暑，萬物生茂。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>伏震為黃、為玉，坤為厚，艮火，故曰溫厚、曰溽暑。艮為君子，坤為萬物、為暑，兌為露。○厚，宋本、汲古作德，依元本。</p><h3 id="蒙之噬嗑" tabindex="-1">蒙之噬嗑 <a class="header-anchor" href="#蒙之噬嗑" aria-label="Permalink to “蒙之噬嗑”">​</a></h3><h3 id="林辞-20" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-20" aria-label="Permalink to “林辞”">​</a></h3><p>畫龍頭頸，文章不成。甘言善語，說辭無名。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>震為龍，艮為頭頸，離為文章，坎隱伏，故不成。初至四正覆震，故曰甘言善語、曰說辭。艮為名，坎隱故無名。○善，依宋元本，汲古作美。</p><h3 id="蒙之賁" tabindex="-1">蒙之賁 <a class="header-anchor" href="#蒙之賁" aria-label="Permalink to “蒙之賁”">​</a></h3><h3 id="林辞-21" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-21" aria-label="Permalink to “林辞”">​</a></h3><p>招禍致凶，來弊我邦。病在手足，不得安息。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>艮手為招、為致，坎為災禍、為凶，艮為邦，伏巽為敝。坎為病，艮手震足，坎居中，故病在手足。艮止為安息，坎險故不安。○邦，音崩，與凶韻。</p><h3 id="蒙之剝" tabindex="-1">蒙之剝 <a class="header-anchor" href="#蒙之剝" aria-label="Permalink to “蒙之剝”">​</a></h3><h3 id="林辞-22" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-22" aria-label="Permalink to “林辞”">​</a></h3><p>履位乘勢，靡有絕斃。皆為隸圉，與眾庶位。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>艮為位，反震為履位乘勢。坤喪，故曰絕斃。艮為隸圉，坤為眾庶。艮僕坤眾合居，故曰與眾庶位。○皆圉，汲古作贊圖，非。位，宋元、汲古作伍，依元本。</p><h3 id="蒙之復" tabindex="-1">蒙之復 <a class="header-anchor" href="#蒙之復" aria-label="Permalink to “蒙之復”">​</a></h3><h3 id="林辞-23" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-23" aria-label="Permalink to “林辞”">​</a></h3><p>獐鹿雉兔，群聚東圃。盧黃白脊，俱往趨逐。九齚十得，君子有喜。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>此用《蒙》象。坤文為雉，艮為獐，震為鹿、為兔，坤為群、為聚、為圃，震東故曰東圃。盧，黑犬。黃、白，皆犬名。《史記李斯傳》：「吾與汝牽黃犬」，《西京雜記》：「李亨有白望犬」。震為玄黃，又為日也。震為追逐、為口、為齚，震數九，故曰九齚，坤數十，故曰十得。震為喜，艮為君子。○圃，依汲古，宋元本皆作囿。趨，依宋元本，汲古作追。</p><h3 id="蒙之無妄" tabindex="-1">蒙之無妄 <a class="header-anchor" href="#蒙之無妄" aria-label="Permalink to “蒙之無妄”">​</a></h3><h3 id="林辞-24" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-24" aria-label="Permalink to “林辞”">​</a></h3><p>織錦未成，緯盡無名。長子逐兔，鹿起失路。見利不得，因無所據。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>巽為帛、為錦、為緯，巽下斷，故曰未成、曰緯盡。艮為名，巽為伏，故無名。震為兔、為長子、為逐、為鹿、為起、為路，巽伏故失路。震為後，巽為利，艮止，故不得。○錦盡，從元本，汲古及宋本作金、作畫，顯為訛字。鹿起失路，依宋元本，汲古作鹿失先路。見，依汲古，宋本作多。後因無所據四字，因疑困之訛字，附記待考。</p><h3 id="蒙之大畜" tabindex="-1">蒙之大畜 <a class="header-anchor" href="#蒙之大畜" aria-label="Permalink to “蒙之大畜”">​</a></h3><h3 id="林辞-25" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-25" aria-label="Permalink to “林辞”">​</a></h3><p>天厭周德，命與仁國。以禮靖民，兵革休息。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>震為周、為德，乾為天，兌絕，故曰天厭周德。艮為國，震為仁，故曰仁國。伏坤為民、為體，艮止為靖，艮剛在外為刀兵、為膚革，艮止，故休息。○靖，元本作靜，依宋本。</p><h3 id="蒙之頤" tabindex="-1">蒙之頤 <a class="header-anchor" href="#蒙之頤" aria-label="Permalink to “蒙之頤”">​</a></h3><h3 id="林辞-26" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-26" aria-label="Permalink to “林辞”">​</a></h3><p>重譯貢芝，來除我憂。善說遂良，與喜相求。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>震為言，正反震，故曰重譯。艮為芝，震為進，故曰貢芝。坤為我、為憂，震樂，故不憂。正反震，故曰善說、故曰喜。艮為求，正反艮，故曰相求。○貢，宋元本作賀，汲古作買，依局本。遂良，疑有訛字。</p><h3 id="蒙之大過" tabindex="-1">蒙之大過 <a class="header-anchor" href="#蒙之大過" aria-label="Permalink to “蒙之大過”">​</a></h3><h3 id="林辞-27" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-27" aria-label="Permalink to “林辞”">​</a></h3><p>膏壤肥澤，人民孔樂。宜利居止，長安富有。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>上卦兌，故曰膏澤，乾為肥，伏坤為壤，為人民，伏震為樂。巽為利，伏艮為居止。坤為長安，乾為富有。○宋本、汲古作膏澤肥壤，依元本，與樂協。富有，依汲古，與止協，宋元皆作富貴。</p><h3 id="蒙之坎" tabindex="-1">蒙之坎 <a class="header-anchor" href="#蒙之坎" aria-label="Permalink to “蒙之坎”">​</a></h3><h3 id="林辞-28" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-28" aria-label="Permalink to “林辞”">​</a></h3><p>白龍黑虎，起鬐暴怒。戰於涿鹿，蚩尤敗走。居止不殆，君安其所。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>震為白、為龍，艮為虎、為黔，故曰黑虎。震為起、為鬐、為威武、為怒、為戰、為鹿，坎水，故曰涿鹿。坎為寇盜，故曰蚩尤。坎險，故曰敗走。艮為居止，震為君。○涿鹿，汲古及常本皆作阪泉，於象亦合，然鹿與上韻，故從宋元本。鬐，汲古作伏，從宋元本。</p><h3 id="蒙之離" tabindex="-1">蒙之離 <a class="header-anchor" href="#蒙之離" aria-label="Permalink to “蒙之離”">​</a></h3><h3 id="林辞-29" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-29" aria-label="Permalink to “林辞”">​</a></h3><p>抱關傳言，聾跛摧筋。眾賤無下，災殃所在。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>伏艮為關、為手，故曰抱關。正反兌口，故曰傳言。坎為耳，震為行，坎伏故聾，震伏，故跛。巽為殞落，兌毀折，故曰摧筋，蓋伏坎為筋也。坎為眾，離為災殃。○言，宋元本作語，筋作殆，依汲古。汲古下二句作「破賤無災，不安其所」，依宋元本。丁晏雲：《淮南子》「聾者可令摧筋」，王制：喑聾跛躃，百工各以其事食」。按：摧筋謂摩筋，摧揉之使柔也。抱關與跛聾為對文，傳言摧筋為對文，《周禮秋官》掌戮職，雲劓者使守關，守關則傳達禁令，故曰傳言，亦賤職也，故曰眾賤。《爾雅釋訓》：下，落也。《儀禮士相見禮》：「執摯至下」，鄭註：下，君所也。無下者，言眾賤無下落，不得其所也。言與筋亦韻，宋元本筋作殆，非也，將對文之義全失，且眾字亦無著落，此又汲古所據之本，前於宋元本之證也。</p><h3 id="蒙之咸" tabindex="-1">蒙之咸 <a class="header-anchor" href="#蒙之咸" aria-label="Permalink to “蒙之咸”">​</a></h3><h3 id="林辞-30" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-30" aria-label="Permalink to “林辞”">​</a></h3><p>憂禍解除，喜至慶來。坐立歡門，與樂為鄰。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>通《損》。震樂，故憂禍解除，喜至慶來。艮坐震立，震歡艮門，故曰坐立歡門。</p><h3 id="蒙之恒" tabindex="-1">蒙之恒 <a class="header-anchor" href="#蒙之恒" aria-label="Permalink to “蒙之恒”">​</a></h3><h3 id="林辞-31" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-31" aria-label="Permalink to “林辞”">​</a></h3><p>折鋒載殳，輿馬放休。行軍依營，天下安寧。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>兌為鋒、為殳、為折，艮覆兌折，故曰折鋒。震為車，故曰載殳。震為馬，在外，故曰放休。坤為軍，伏艮為營，艮止，故曰依營，言不出也。坤為天下、為安寧。○輿，汲古作與。行軍，宋本、汲古作狩軍，依元本。</p><h3 id="蒙之遯" tabindex="-1">蒙之遯 <a class="header-anchor" href="#蒙之遯" aria-label="Permalink to “蒙之遯”">​</a></h3><h3 id="林辞-32" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-32" aria-label="Permalink to “林辞”">​</a></h3><p>至德之君，仁政且溫。伊呂股肱，國富民安。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>乾為君、為至德、為仁，艮火，故曰溫。艮為臣，故曰伊呂。巽為股，艮為肱，故曰伊呂股肱。伏坤為國、為民，乾富艮安。</p><h3 id="蒙之大壯" tabindex="-1">蒙之大壯 <a class="header-anchor" href="#蒙之大壯" aria-label="Permalink to “蒙之大壯”">​</a></h3><h3 id="林辞-33" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-33" aria-label="Permalink to “林辞”">​</a></h3><p>千里望城，不見山青。老兔蝦●，遠絕無家。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>震為千里，艮為城、為望、為山，震東方，色青，艮伏故不見。震為兔、為蝦●。艮為家，艮覆，故無家。○●，汲古作蟆。蟆，●同。山青，依元本，汲古作青山。</p><h3 id="蒙之晉" tabindex="-1">蒙之晉 <a class="header-anchor" href="#蒙之晉" aria-label="Permalink to “蒙之晉”">​</a></h3><h3 id="林辞-34" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-34" aria-label="Permalink to “林辞”">​</a></h3><p>有莘季女，為夏妃後。貴夫壽子，毋字四海。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>坤為茅茹，故曰有莘。艮為季，坤女，故曰有莘季女。離為夏。坤為妃後。艮為貴、為壽，坎為夫、為中子，坤為母、為字。字者，養也。坤為水、為海，反震，卦數四，故曰四海。有莘氏，大禹之母。</p><h3 id="蒙之明夷" tabindex="-1">蒙之明夷 <a class="header-anchor" href="#蒙之明夷" aria-label="Permalink to “蒙之明夷”">​</a></h3><h3 id="林辞-35" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-35" aria-label="Permalink to “林辞”">​</a></h3><p>不虞之患，禍至無門。奄忽暴卒，痛傷我心。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>坤為患、為禍，坎為憂虞，艮為門，三至五艮覆，故曰無門。坤死故曰卒。坎為心、為痛，坤為我。《道德指歸論》：「道之為物，窺之無戶，察之無門」，無門，言不知禍之所自來也。</p><h3 id="蒙之家人" tabindex="-1">蒙之家人 <a class="header-anchor" href="#蒙之家人" aria-label="Permalink to “蒙之家人”">​</a></h3><h3 id="林辞-36" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-36" aria-label="Permalink to “林辞”">​</a></h3><p>飛鷹退去，不食雉雞。憂患解除，主君安居。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>此用《蒙》象。艮為鷹、為飛，震反，故退去。本卦離為雉，巽為雞，坎為食，震為解除，上卦兌覆，故不食。坎為憂患、為君主，艮為安居。○雉雞，宋元本作鄰鳥，依汲古。解除，汲古作心解，依宋元本。主君，宋本、汲古作君主，依元本。</p><h3 id="蒙之睽" tabindex="-1">蒙之睽 <a class="header-anchor" href="#蒙之睽" aria-label="Permalink to “蒙之睽”">​</a></h3><h3 id="林辞-37" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-37" aria-label="Permalink to “林辞”">​</a></h3><p>跮蹉側跌，申酉為祟。戌亥滅明，顏子隱藏。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>二折震成兌，故跮蹉側失。兌西方金，故曰申酉為祟。艮居戌亥，艮為明，艮伏故滅明。艮為顏，艮伏，故顏子隱藏。○蹉，元本作差，差蹉古通。申酉、戌亥，蓋古占術。</p><h3 id="蒙之蹇" tabindex="-1">蒙之蹇 <a class="header-anchor" href="#蒙之蹇" aria-label="Permalink to “蒙之蹇”">​</a></h3><h3 id="林辞-38" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-38" aria-label="Permalink to “林辞”">​</a></h3><p>司祿憑怒，謀議無道。商氏失政，殷人乏嗣。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>《漢書天文志》：「司祿，文昌第六星」。此用《蒙》象。艮為星、為官，故曰司祿。震為怒、為言，故為議。坎為心，故曰謀議。艮為道，坎伏，故曰無道。震為子、為人。子者，殷商之姓，坤殺，故無子而乏嗣。○氏，宋本、汲古作民，從元本。</p><h3 id="蒙之解" tabindex="-1">蒙之解 <a class="header-anchor" href="#蒙之解" aria-label="Permalink to “蒙之解”">​</a></h3><h3 id="林辞-39" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-39" aria-label="Permalink to “林辞”">​</a></h3><p>望雞得雛，冀馬獲駒。大德生少，有廖從居。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>巽為雞，離目為望，巽伏，故不得雞而得雛，震為雛也。坎為馬，震為雛、為駒。下二句疑有訛字，義皆未詳。○雛，依汲古，宋元本作雉。</p><h3 id="蒙之損" tabindex="-1">蒙之損 <a class="header-anchor" href="#蒙之損" aria-label="Permalink to “蒙之損”">​</a></h3><h3 id="林辞-40" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-40" aria-label="Permalink to “林辞”">​</a></h3><p>忉忉怛怛，如將不活。黍稷之恩，靈輒以存。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>《詩陳風》「心焉忉忉」，《傳》「忉忉，憂貌」，坤為憂，故曰忉忉怛怛。怛，亦憂也。坤死，故曰不活。震為黍稷、為恩，坤虛為餓，故曰靈輒。《左傳宣二年》：「初，趙盾田，見靈輒，餓食之」，故曰靈輒以存。○忉忉，汲古訛切切，俗本又訛叨叨，依宋元本。又汲古多「獲生保年」四字，依宋元本。</p><h3 id="蒙之益" tabindex="-1">蒙之益 <a class="header-anchor" href="#蒙之益" aria-label="Permalink to “蒙之益”">​</a></h3><h3 id="林辞-41" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-41" aria-label="Permalink to “林辞”">​</a></h3><p>噂噂囁囁，夜作晝匿。謀議我資，來攻我室。空盡我財，幾無以食。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>初至五正反震相對，故曰噂噂囁囁。噂囁，對語也。此句宋元本、汲古原作莫莫輯輯，於卦象不切，依節之艮校。坤為夜，與震連，故夜作晝。伏乾為大明、為晝，巽為伏，故曰晝匿。坤為財、為我，正反震，故曰謀議我資。艮為室，震為伐、為攻，坤虛故財空。震為食，坤飢，故無食。○來，依汲古，宋元本作求。</p><h3 id="蒙之夬" tabindex="-1">蒙之夬 <a class="header-anchor" href="#蒙之夬" aria-label="Permalink to “蒙之夬”">​</a></h3><h3 id="林辞-42" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-42" aria-label="Permalink to “林辞”">​</a></h3><p>天之所壞，不可強支。眾口指笑，雖貴必危。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>乾為天，兌毀，故曰天之所壞，不可強支。兌為口、為笑，坤眾，故曰眾口。伏艮為指、為貴，兌毀，一陰將盡故危。○指，汲古本作遭，乃嘈之訛字，蠱之艮作嘈嘈。首二句本《國語》「天之所支不可壞也」，所壞不可支也。</p><h3 id="蒙之姤" tabindex="-1">蒙之姤 <a class="header-anchor" href="#蒙之姤" aria-label="Permalink to “蒙之姤”">​</a></h3><h3 id="林辞-43" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-43" aria-label="Permalink to “林辞”">​</a></h3><p>目動睫瞤，喜來加身。舉家蒙歡，吉利無殃。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>《說文》：「瞤，目動也」，《西京雜記》：「陸賈曰：目瞤得酒食」。伏震為動、為喜，坤為身。目睫象未詳。○睫，汲古本作頰，俗木多從之，非，依宋元本。《漢書》：「睫瞤得酒肉。」</p><h3 id="蒙之萃" tabindex="-1">蒙之萃 <a class="header-anchor" href="#蒙之萃" aria-label="Permalink to “蒙之萃”">​</a></h3><h3 id="林辞-44" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-44" aria-label="Permalink to “林辞”">​</a></h3><p>黿羹芬香，染指拂裳。口飢於手，子公恨饞。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>艮為黿，坤為羹，巽為臭，故曰芬香。艮為指、為拂，坤水，故染指。坤為裳，艮手，故拂裳。兌為口，坤為飢，口飢於手者，言口飢而恃手也。於，依也。《孔融書》：「舉杯相於」，曹植《樂府》：「心相於」，《杜甫詩》：「良友幸相於」，皆作依恃解，是其證。子公，鄭公子宋也。《左傳宣四年》：「楚人獻黿於鄭靈公，公子宋與子家將見，子公之食指動，以示子家曰：「他日我如此，必嘗異味」，及入，宰夫將解黿，相視而笑，公問，子家以告。及食大夫黿，召子公而弗與，子公怒，染指於鼎，嘗之而出。林詞全述其事。○拂裳，依汲古，古人衣袖寬博，言染指之時須拂裳也，宋元本作弗嘗，於、子公，依宋元本，汲古誤打、誤公子，饞作讒。</p><h3 id="蒙之升" tabindex="-1">蒙之升 <a class="header-anchor" href="#蒙之升" aria-label="Permalink to “蒙之升”">​</a></h3><h3 id="林辞-45" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-45" aria-label="Permalink to “林辞”">​</a></h3><p>天福所豐，兆如飛龍。成子得志，六二以興。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>伏乾故曰天福、曰豐，震為飛、為龍，坤坼為兆，故曰兆如飛龍。伏艮為成，震子，故曰成子。震為興，巽為志，故曰得志。坤數二，伏乾數六，故曰六二。翟雲升雲：「六二謂十二世也。」愚按：《莊子胠篋篇》：「田成子十二世有齊國」，《釋文》雲：「自敬仲奔齊，至莊子九世，知齊政自大公和至威王三世而有齊國，共十二世」，故曰六二以興。○以，從元本，汲古及常本多作已。二，宋本作三，非，從汲古。</p><h3 id="蒙之困" tabindex="-1">蒙之困 <a class="header-anchor" href="#蒙之困" aria-label="Permalink to “蒙之困”">​</a></h3><h3 id="林辞-46" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-46" aria-label="Permalink to “林辞”">​</a></h3><p>氓伯易絲，抱布自媒。棄禮急情，卒罹悔憂。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>《詩氓》之篇：「氓之蚩蚩，抱布貿絲。匪來貿絲，來即我謀」。布，幣也。貿即易也。伏震為伯，巽為絲、為布，巽為商賈，故抱布易絲。伏艮為抱，坎為合、為媒、為憂。○易絲，宋本、汲古作以婚，依元本。罹，依宋本，元本作離，義同。</p><h3 id="蒙之井" tabindex="-1">蒙之井 <a class="header-anchor" href="#蒙之井" aria-label="Permalink to “蒙之井”">​</a></h3><h3 id="林辞-47" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-47" aria-label="Permalink to “林辞”">​</a></h3><p>夏姬親附，心聽悅喜。利以搏取，無言不許。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>通《噬嗑》。離為夏，震為姬，兌悅，故親附、故悅喜。坎為心、為聽，巽為利，艮為搏取，震為言。○姬，汲古作姒，依宋元本作震辭。按：《左傳》：巫臣嘗止子反取夏姬，後竟自取，林似指此事。</p><h3 id="蒙之革" tabindex="-1">蒙之革 <a class="header-anchor" href="#蒙之革" aria-label="Permalink to “蒙之革”">​</a></h3><h3 id="林辞-48" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-48" aria-label="Permalink to “林辞”">​</a></h3><p>南山昊天，刺政閔身。疾悲無辜，背憎為仇。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>通《蒙》。震南艮山，故曰南山。本卦離為夏，故曰昊天。《爾雅釋天》：「夏為昊天。」註：言氣皓旰也。坎為刺，坤為政、為身，坎為憂閔、為悲、為疾、為憎、為仇，坤為辜，坤虛故無。艮為背，下坎，故曰背憎。《詩小雅》：「節彼南山，不吊昊天」，為刺譏厲王之詩。林辭全用其意。○昊，從宋元本，汲古誤旻，元本作艮，林象亦合。</p><h3 id="蒙之鼎" tabindex="-1">蒙之鼎 <a class="header-anchor" href="#蒙之鼎" aria-label="Permalink to “蒙之鼎”">​</a></h3><h3 id="林辞-49" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-49" aria-label="Permalink to “林辞”">​</a></h3><p>三人為旅，俱歸北海。入門上堂，拜謁王母。勞賜我酒，歡樂無疆。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>通《屯》。震為人，後天數三，震為商旅，故曰三人為旅。坤為海水，位北，故曰北海。震為歸，故歸北海。艮為門堂，震為入、為上，艮為拜，震為謁、為王，坤母，故曰王母。坎為勞、為酒，坤為我。象全用旁通。○宋元本作井林，旁通《噬嗑》，於象不盡合，汲古少「歡樂無疆」四字，不協。</p><h3 id="蒙之震" tabindex="-1">蒙之震 <a class="header-anchor" href="#蒙之震" aria-label="Permalink to “蒙之震”">​</a></h3><h3 id="林辞-50" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-50" aria-label="Permalink to “林辞”">​</a></h3><p>愆淫旱疾，傷害稼穡。喪制病來，農人無食。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>愆者，不及淫者過也。艮為火，坎為疾，故曰旱疾。震為稼穡，艮火，故傷害禾稼。震為人、為農、為食，稼傷，故無食。震初至四與無妄初至四同，京房以無妄為大旱卦，自虞翻莫明其義，由艮火之象失傳也。○愆，汲古作陽，疾作病，製作刈，茲從宋元本。林詞訛誤若此者，直無如何。又宋元本作井林，象亦合。</p><h3 id="蒙之艮" tabindex="-1">蒙之艮 <a class="header-anchor" href="#蒙之艮" aria-label="Permalink to “蒙之艮”">​</a></h3><h3 id="林辞-51" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-51" aria-label="Permalink to “林辞”">​</a></h3><p>攫飯把肉，以就口食。所往必得，無有虛乏。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>坎為飲、為肉，艮手為攫、為把，互震為口、為食、為往，坎為得，故無有虛乏。○所，元刊作萬，依宋本、汲古。</p><h3 id="蒙之漸" tabindex="-1">蒙之漸 <a class="header-anchor" href="#蒙之漸" aria-label="Permalink to “蒙之漸”">​</a></h3><h3 id="林辞-52" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-52" aria-label="Permalink to “林辞”">​</a></h3><p>鳥飛無翼，兔走折足。雖欲會同，未得所欲。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>離為鳥、為飛，震為翼，震伏，巽寡髪，故無翼。震為兔、為走、為足，震伏坎折，故曰折足。○所欲，汲古作已惑，依宋元。</p><h3 id="蒙之歸妹" tabindex="-1">蒙之歸妹 <a class="header-anchor" href="#蒙之歸妹" aria-label="Permalink to “蒙之歸妹”">​</a></h3><h3 id="林辞-53" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-53" aria-label="Permalink to “林辞”">​</a></h3><p>體重飛難，未能逾關。行坐憂愁，不離室垣。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>此用《蒙》象。坤為身、為重，故曰體重。震為飛，坎陷，故難飛。艮為關，坤閉，故未能逾關。震為逾、為行，坎為憂愁、為宮室，坎陷，故不離。○宋元本無第三句，汲古有有是。未能，依元本，宋本、汲古作不得。</p><h3 id="蒙之豐" tabindex="-1">蒙之豐 <a class="header-anchor" href="#蒙之豐" aria-label="Permalink to “蒙之豐”">​</a></h3><h3 id="林辞-54" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-54" aria-label="Permalink to “林辞”">​</a></h3><p>四雄並處，人民愁苦。擁兵西東，不得安所。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>震為雄，卦數四，故曰四雄。互大坎為人民，坎憂，故愁苦。兌為斧、為兵，坎聚，故曰擁兵。震東兌西，震動坎險，故不安。○西東，汲古作東西，依宋元本。</p><h3 id="蒙之旅" tabindex="-1">蒙之旅 <a class="header-anchor" href="#蒙之旅" aria-label="Permalink to “蒙之旅”">​</a></h3><h3 id="林辞-55" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-55" aria-label="Permalink to “林辞”">​</a></h3><p>譯重關牢，求解己憂。心咸乃成，與善並居。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>通《節》。中爻反正震，故曰譯重。坎為牢，震為開、為解，艮為求，坎為憂、為心。辭皆費解，必有訛字。○咸，宋元本作惑。譯重，元本作重譯，非。譯重與關牢對文。牢，固也，依汲古。</p><h3 id="蒙之巽" tabindex="-1">蒙之巽 <a class="header-anchor" href="#蒙之巽" aria-label="Permalink to “蒙之巽”">​</a></h3><h3 id="林辞-56" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-56" aria-label="Permalink to “林辞”">​</a></h3><p>患解憂除，王母相於。與喜俱來，使我安居。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>通《震》。為樂，故無憂患。震為王，巽為母，相於者，相依也。義已見前《萃》卦。震為喜，艮為安居。皆用旁通。○於，從宋元本，汲古作予。王，元本作皇，義同。</p><h3 id="蒙之兌" tabindex="-1">蒙之兌 <a class="header-anchor" href="#蒙之兌" aria-label="Permalink to “蒙之兌”">​</a></h3><h3 id="林辞-57" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-57" aria-label="Permalink to “林辞”">​</a></h3><p>冬生不華，老女無家。霜冷蓬室，更為枯株。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>伏坎為冬，震為生，兌為華，冬，故不華。《大過》以兌為老婦，艮為家，艮伏，故老女無家。坎為霜、為冷，艮為室，震為蓬，故曰蓬室。巽為木，互離，故曰枯株。○更，依元刊，汲古作競。</p><h3 id="蒙之渙" tabindex="-1">蒙之渙 <a class="header-anchor" href="#蒙之渙" aria-label="Permalink to “蒙之渙”">​</a></h3><h3 id="林辞-58" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-58" aria-label="Permalink to “林辞”">​</a></h3><p>震慄恐懼，多所畏惡。行道留難，不可以步。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>坎為恐懼、為畏惡。震為道、為行，坎陷，故留難，故不可步。○步，汲古作涉，從宋元本。</p><h3 id="蒙之節" tabindex="-1">蒙之節 <a class="header-anchor" href="#蒙之節" aria-label="Permalink to “蒙之節”">​</a></h3><h3 id="林辞-59" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-59" aria-label="Permalink to “林辞”">​</a></h3><p>三夫共妻，莫適為雌。子無名氏，翁不可知。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>《節》長中少三男俱備，祇兌為女象，故曰三夫共妻。適，主也。莫適為雌，言兌女無所適從也。震為子，艮為名，坎隱，故無名氏。震為父，翁者，父也。坎隱，又二至五正反皆震，故曰不知。此林為愚求索林詞知其用象之始，故志其艱於此。○翁，宋元本作公，義同。</p><h3 id="蒙之中孚" tabindex="-1">蒙之中孚 <a class="header-anchor" href="#蒙之中孚" aria-label="Permalink to “蒙之中孚”">​</a></h3><h3 id="林辞-60" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-60" aria-label="Permalink to “林辞”">​</a></h3><p>早凋被霜，花葉不長。非時為災，家受其殃。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>震為花葉，兌為霜，巽為隕落，故曰凋、曰不長。艮為時、為家，兌折巽落，故為災殃。○災，依宋本，元本作落。早，元本作草，依宋本、汲古。</p><h3 id="蒙之小過" tabindex="-1">蒙之小過 <a class="header-anchor" href="#蒙之小過" aria-label="Permalink to “蒙之小過”">​</a></h3><h3 id="林辞-61" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-61" aria-label="Permalink to “林辞”">​</a></h3><p>雉兔之東，狼虎所從。貪饕凶惡，不可止息。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>艮為鳥、為雉，震為兔、為東、為之，之，往也。艮為狼虎，震為從，兌為食，震亦為食，故曰貪饕。兌毀為凶惡。艮為止息，坎險，故不可止息。○饕，依汲古，宋元刊作叨。</p><h3 id="蒙之既濟" tabindex="-1">蒙之既濟 <a class="header-anchor" href="#蒙之既濟" aria-label="Permalink to “蒙之既濟”">​</a></h3><h3 id="林辞-62" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-62" aria-label="Permalink to “林辞”">​</a></h3><p>馬驚破車，主墮深溝。身死魂去，離其室廬。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>此用《蒙》象。震為馬、為車、為驚，坎破，故馬驚破車。震為主，坎為陷，故曰主墮。坎為溝，在下，故曰深溝。坤為身、為死，故曰身死。震為神、為魂、為去。艮為室廬。○主，依宋元本，汲古作王。</p><h3 id="蒙之未濟" tabindex="-1">蒙之未濟 <a class="header-anchor" href="#蒙之未濟" aria-label="Permalink to “蒙之未濟”">​</a></h3><h3 id="林辞-63" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-63" aria-label="Permalink to “林辞”">​</a></h3><p>山林麓藪，非人所處。鳥獸無禮，使我心苦。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>此用《蒙》象。艮為山，震為林麓，故曰山林麓藪。震為人，坎險，故人不可處。艮為鳥、為獸，坤為禮，坎隱伏，故無禮。坎為心、為勞苦。○非人所處，從元本，汲古作「兆人所往」，兆因與非形近，訛。</p>',322)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
